<script lang="ts">
	import { onMount } from 'svelte'; import { cancelBooking, myBookings } from '$lib/api/bookings'; import type { Booking } from '$lib/api/types'; import { auth } from '$lib/stores/auth.svelte'; import BookingTable from '$lib/components/BookingTable.svelte'; import Card from '$lib/components/ui/Card.svelte'; import Alert from '$lib/components/ui/Alert.svelte'; let bookings = $state<Booking[]>([]); let loading = $state(true); let error = $state('');
	async function load() { loading = true; error = ''; if (!auth.user) { error = 'Log in to view your bookings.'; loading = false; return; } try { bookings = (await myBookings()).content; } catch (reason) { error = reason instanceof Error ? reason.message : 'Could not load bookings.'; } finally { loading = false; } }
	onMount(async () => { if (!auth.ready) await auth.restore(); await load(); }); async function cancel(id: number) { try { await cancelBooking(id); await load(); } catch (reason) { error = reason instanceof Error ? reason.message : 'Could not cancel booking.'; } }
</script>
<div class="space-y-5"><div><h1 class="text-2xl font-semibold">My bookings</h1><p class="text-sm text-slate-600">Your upcoming and past appointments.</p></div><Card>{#if error}<Alert>{error}</Alert>{/if}{#if loading}<p class="text-sm text-slate-500">Loading bookings…</p>{:else if bookings.length === 0}<p class="text-sm text-slate-500">No bookings yet.</p>{:else}<BookingTable {bookings} onCancel={cancel} />{/if}</Card></div>
